import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u03")

L(1, "Vogais curtas e longas", "a/aa, o/oo, e/ee: uma letra a mais muda a palavra.",
  ["Distinguir vogais curtas de vogais longas", "Ler e reconhecer pares como man/maan e zon/zoon"],
  vocab=[V("v-man","man","homem","noun","de","mannen"), V("v-maan","maan","lua","noun","de","manen"),
         V("v-zon","zon","sol","noun","de"), V("v-zoon","zoon","filho","noun","de","zonen"),
         V("v-bus","bus","autocarro","noun","de","bussen"), V("v-bed","bed","cama","noun","het","bedden"),
         V("v-been","been","perna","noun","het","benen")],
  ex=[("de man — de maan","o homem — a lua"),("de zon — de zoon","o sol — o filho"),("het bed — het been","a cama — a perna")],
  gram=[G("g-vogais-curtas-longas","Vogais curtas e longas","Numa sílaba que termina em consoante, uma vogal escrita **uma vez** é curta (*man*, *zon*, *bed*) e escrita **duas vezes** é longa (*maan*, *zoon*, *been*). A diferença muda o sentido: *man* (homem) não é *maan* (lua).",
    [("man / maan","homem / lua"),("zon / zoon","sol / filho")],
    "Em português o comprimento da vogal não muda o significado das palavras; em neerlandês muda, por isso vale a pena exagerar a vogal longa ao início.")],
  review=["v-mijn","v-heten"],
  exs=[
    LI("de maan", ["de maan"], "a lua", "«aa» é um «a» aberto e longo; em «man» o «a» é curto e mais fechado.", ["v-maan"]),
    MC("Qual destas palavras tem uma vogal LONGA?", ["*maan","man|Um só «a» numa sílaba fechada: vogal curta.","zon|Um só «o» numa sílaba fechada: vogal curta."], "Duas vogais iguais (aa, oo, ee, uu) indicam uma vogal longa.", ["v-maan"]),
    MA([("man","homem"),("maan","lua"),("zon","sol"),("zoon","filho")], "Repare como cada par difere só numa vogal.", ["v-man","v-maan","v-zon","v-zoon"]),
    FE(["Mijn","zon","heet","Tom."], 1, "zoon", "«Zon» é o sol; o filho é «zoon», com «o» longo.", ["v-zoon","v-zon"]),
    AR("bed","a cama","het", "«Het bed». Muitas palavras curtas e comuns usam «het»; é preciso memorizá-las.", ["v-bed"]),
    AR("maan","a lua","de", "«De maan». A maioria dos substantivos usa «de».", ["v-maan"]),
    TR("pt-nl","o autocarro", ["(de )bus"], "«De bus». Diz-se com «u» curto, parecido com o «â» de «cama».", ["v-bus"]),
    FB("Mijn ___ heet Pedro.", ["zoon"], "«Zoon» = filho. «Zon» (sol) e «maan» (lua) não fazem sentido aqui.", ["v-zoon"], choices=["zoon","zon","maan"], tr="O meu filho chama-se Pedro."),
    LI("de man en de zoon", ["de man en de zoon"], "o homem e o filho", "Vogal curta em «man», vogal longa em «zoon».", ["v-man","v-zoon"]),
    TR("nl-pt","het been", ["(a )perna"], "«Been» com «ee» longo = perna. (Também significa «osso».)", ["v-been"]),
  ], diff=1, mins=5)

L(2, "O «g» e o «ch»", "O som mais típico do neerlandês: raspado, no fundo da garganta.",
  ["Pronunciar o «g» e o «ch» neerlandeses", "Aprender palavras frequentes com estes sons"],
  vocab=[V("v-acht","acht","oito","numeral"), V("v-nacht","nacht","noite","noun","de","nachten"),
         V("v-lachen","lachen","rir","verb",note="ik lach, jij lacht"), V("v-gaan","gaan","ir","verb",note="ik ga, jij gaat, u gaat, hij gaat"),
         V("v-graag","graag","com gosto|sim, por favor","adverb",note="«Ja, graag!» = Sim, por favor!"),
         V("v-gracht","gracht","canal","noun","de","grachten",note="Os canais das cidades, como em Amesterdão."),
         V("v-geld","geld","dinheiro","noun","het")],
  ex=[("Acht uur.","Oito horas."),("Ja, graag!","Sim, por favor!"),("Ik ga naar Amsterdam.","Vou para Amesterdão.")],
  gram=[G("g-som-g-ch","O «g» e o «ch»","Nos Países Baixos, **g** e **ch** soam praticamente igual: um som raspado no fundo da garganta, parecido com o «j» espanhol de *jamón*. No sul do país e na Flandres o som é mais suave. Em **sch** no início da palavra lê-se «s» + esse som: *school*.",
    [("goed","bom / bem"),("acht","oito"),("school","escola")],
    "Nunca leia o «g» neerlandês como o «g» de «gato» nem como o de «gente».")],
  review=["v-goedemorgen","v-goedenacht","v-koffie"],
  exs=[
    MC("Como soa o «g» de «goed»?", ["*Um som raspado na garganta, como o «j» espanhol","Como o «g» de «gato»|Esse som não existe em palavras neerlandesas comuns.","Como o «g» de «gente»|Não: o «g» neerlandês é gutural."], "O «g» e o «ch» neerlandeses partilham o mesmo som gutural.", ["v-goedemorgen"]),
    LI("acht", ["acht"], "oito", "O «ch» é o mesmo som raspado do «g».", ["v-acht"]),
    MA([("acht","oito"),("nacht","noite"),("geld","dinheiro"),("gracht","canal")], "Todas estas palavras têm o som gutural.", ["v-acht","v-nacht","v-geld","v-gracht"]),
    AR("geld","o dinheiro","het", "«Het geld».", ["v-geld"]),
    AR("gracht","o canal","de", "«De gracht» — plural «grachten».", ["v-gracht"]),
    CJ("gaan","ik","Ik ___ naar Amsterdam.", ["ga"], "gaan: ik ga, jij gaat, u gaat, hij/zij gaat. A forma de «ik» é curta: ga.", ["v-gaan"]),
    CJ("gaan","jij","Jij ___ naar Utrecht.", ["gaat"], "Com «jij» acrescenta-se -t: jij gaat. Na pergunta, o -t cai: «Ga jij naar Utrecht?».", ["v-gaan"]),
    DL([("Sanne","Wil je koffie?","Queres café?"),("Pedro","")], ["*Ja, graag!","Ja, acht!|«Acht» é o número oito.","Goedenacht!|Isso é uma despedida noturna."], "«Ja, graag!» é a forma natural de aceitar algo: «sim, por favor».", ["v-graag","v-koffie"]),
    TR("nl-pt","Ja, graag!", ["Sim, por favor","Sim, com (muito )gosto","Sim, obrigad[o|a]"], "«Graag» exprime vontade: aceitar uma oferta com gosto.", ["v-graag"]),
    LI("Goedenacht!", ["Goedenacht"], "Boa noite! (ao despedir-se tarde)", "Dois sons guturais: o «g» inicial e o «ch» final.", ["v-goedenacht","v-nacht"]),
  ], diff=1, mins=5)

L(3, "ui, ij e ei", "Os ditongos que não existem em português.",
  ["Pronunciar «ui»", "Saber que «ij» e «ei» soam igual"],
  vocab=[V("v-huis","huis","casa","noun","het","huizen"), V("v-tuin","tuin","jardim","noun","de","tuinen"),
         V("v-trein","trein","comboio","noun","de","treinen"), V("v-wijn","wijn","vinho","noun","de"),
         V("v-ijs","ijs","gelado|gelo","noun","het"), V("v-bruin","bruin","castanho","adjective"),
         V("v-klein","klein","pequeno","adjective")],
  ex=[("Het huis is klein.","A casa é pequena."),("De trein is laat.","O comboio está atrasado."),("Een ijs, alstublieft.","Um gelado, por favor.")],
  gram=[G("g-ui-ij-ei","ui, ij e ei","**ij** e **ei** soam exatamente igual (aproximadamente «éi» aberto): *wijn*, *trein*. A escolha entre ij e ei tem de ser memorizada. **ui** não existe em português: comece com um «â» e feche-o num «i» com os lábios arredondados: *huis*, *tuin*.",
    [("mijn / klein","meu / pequeno"),("huis / tuin","casa / jardim")],
    "O «ij» conta como uma só letra: no início da palavra escrevem-se as duas em maiúscula, como em IJsselmeer.")],
  review=["v-mijn","v-is","v-alstublieft"],
  exs=[
    LI("het huis", ["het huis"], "a casa", "«ui» começa como um «â» e acaba num «i» arredondado.", ["v-huis"]),
    MC("Como se escreve «comboio» em neerlandês?", ["*trein","trijn|Soa igual, mas esta palavra escreve-se com «ei».","train|Isso é inglês."], "«ij» e «ei» soam igual, por isso a grafia tem de ser memorizada.", ["v-trein"]),
    MA([("huis","casa"),("tuin","jardim"),("trein","comboio"),("wijn","vinho")], "ui em huis e tuin; ei/ij em trein e wijn.", ["v-huis","v-tuin","v-trein","v-wijn"]),
    AR("huis","a casa","het", "«Het huis» — plural «huizen».", ["v-huis"]),
    AR("trein","o comboio","de", "«De trein».", ["v-trein"]),
    FB("Mijn ___ is klein.", ["huis"], "«Mijn huis is klein» = a minha casa é pequena.", ["v-huis","v-klein"], choices=["huis","wijn","ijs"], tr="A minha casa é pequena."),
    TR("nl-pt","Het huis is klein.", ["A casa é pequena"], "Os adjetivos depois de «is» não mudam: «klein».", ["v-huis","v-klein"]),
    TR("pt-nl","um gelado, por favor", ["[een|één] ijs(,) [alstublieft|alsjeblieft]"], "«Ijs» é gelado (e também gelo). Com um empregado, «alstublieft».", ["v-ijs","v-alstublieft"]),
    FE(["Het","ijs","is","bruijn."], 3, "bruin", "Castanho escreve-se «bruin», com «ui».", ["v-bruin"]),
    WO("A minha casa é pequena.", ["Mijn","huis","is","klein"], "Sujeito (mijn huis), verbo (is), adjetivo (klein).", ["v-huis","v-klein"]),
    LI("De trein is klein.", ["De trein is klein"], "O comboio é pequeno.", "«trein» e «klein» rimam: ambos com o som «ei».", ["v-trein","v-klein"]),
  ], diff=2, mins=6)

L(4, "oe, eu, ou e au", "Mais quatro sons: um fácil, um novo e dois que soam igual.",
  ["Ler «oe» como «u»", "Pronunciar «eu»", "Saber que «ou» e «au» soam igual"],
  vocab=[V("v-boek","boek","livro","noun","het","boeken"), V("v-stoel","stoel","cadeira","noun","de","stoelen"),
         V("v-deur","deur","porta","noun","de","deuren"), V("v-leuk","leuk","giro|engraçado|agradável","adjective",note="«Leuk!» = Que giro! / Que fixe!"),
         V("v-koud","koud","frio","adjective"), V("v-oud","oud","velho","adjective"),
         V("v-blauw","blauw","azul","adjective"), V("v-vrouw","vrouw","mulher","noun","de","vrouwen")],
  ex=[("Het boek is oud.","O livro é velho."),("Het is koud!","Está frio!"),("Leuk!","Que giro!")],
  gram=[G("g-oe-eu-ou","oe, eu, ou/au","**oe** soa como o «u» português: *boek* ≈ «buk». **eu** é parecido com o «eu» francês de *bleu*: diga «e» com os lábios arredondados. **ou** e **au** soam igual (≈ «âu»): *koud*, *blauw*.",
    [("boek / stoel","livro / cadeira"),("deur / leuk","porta / giro"),("koud / blauw","frio / azul")])],
  review=["v-is","v-goed"],
  exs=[
    LI("Het boek is oud.", ["Het boek is oud"], "O livro é velho.", "«oe» = «u»; «ou» ≈ «âu».", ["v-boek","v-oud"]),
    MA([("boek","livro"),("stoel","cadeira"),("deur","porta"),("vrouw","mulher")], "oe em boek e stoel, eu em deur, ou em vrouw.", ["v-boek","v-stoel","v-deur","v-vrouw"]),
    MC("Que par de grafias soa igual?", ["*ou / au","oe / eu|«oe» soa como «u»; «eu» é um som diferente.","ui / oe|«ui» é um ditongo; «oe» é um «u» simples."], "«koud» e «blauw» têm o mesmo som; «ij» e «ei» também.", ["v-koud","v-blauw"]),
    AR("boek","o livro","het", "«Het boek».", ["v-boek"]),
    AR("stoel","a cadeira","de", "«De stoel».", ["v-stoel"]),
    TR("nl-pt","Het is koud!", ["[Está|Faz|Está muito] frio"], "Para o tempo usa-se «het is»: het is koud = está frio.", ["v-koud"]),
    FB("De ___ is blauw.", ["deur"], "«De deur is blauw» = a porta é azul.", ["v-deur","v-blauw"], choices=["deur","koud","leuk"], tr="A porta é azul."),
    EX("Leuk!", "Agradável!", "Um amigo conta que vai a Lisboa e tu respondes «Leuk!». O que quer dizer?", ["*Que giro! / Que fixe!","Que frio!|Isso seria «koud».","Que pena!|Isso seria «jammer»."], "«Leuk» é uma das palavras mais usadas: giro, fixe, agradável.", ["v-leuk"]),
    FE(["De","vrauw","is","oud."], 1, "vrouw", "Soa igual a «au», mas «mulher» escreve-se «vrouw».", ["v-vrouw"]),
    TR("pt-nl","O livro é azul.", ["Het boek is blauw"], "«Het boek» + «is» + adjetivo.", ["v-boek","v-blauw"], bank=["Het","boek","is","blauw","De","stoel"]),
  ], diff=2, mins=5)

L(5, "Consoantes: w, v, j, z e sch", "As consoantes que mais confundem os portugueses.",
  ["Pronunciar w, v e j corretamente", "Ler «sch» e o «z» sonoro"],
  vocab=[V("v-water","water","água","noun","het"), V("v-fiets","fiets","bicicleta","noun","de","fietsen"),
         V("v-vis","vis","peixe","noun","de","vissen"), V("v-school","school","escola","noun","de","scholen"),
         V("v-zes","zes","seis","numeral"), V("v-jaar","jaar","ano","noun","het","jaren"),
         V("v-zee","zee","mar","noun","de","zeeën")],
  ex=[("Ik ga naar school.","Vou para a escola."),("Zes jaar.","Seis anos."),("Een fiets en een vis.","Uma bicicleta e um peixe.")],
  gram=[G("g-consoantes","Consoantes traiçoeiras","**w**: os lábios quase se tocam, entre o «v» e o «u» (*water*). **v** no início soa muitas vezes quase como «f» (*vis* ≈ «fis»). **j** soa como o «i» de «iate», nunca como o «j» de «janela» (*ja*, *jaar*). **z** é sempre sonoro, como em «zebra». **sch** = «s» + o som raspado do «g» (*school*).",
    [("ja","sim — «iá»"),("water","água"),("school","escola")],
    "O «j» português de «janela» não existe em neerlandês: aparece só em palavras estrangeiras como «journalist».")],
  review=["v-gaan","v-ja"],
  exs=[
    MC("Como se lê o «j» de «jaar»?", ["*Como o «i» de «iate»","Como o «j» de «janela»|Esse som só aparece em palavras estrangeiras.","Como o «r» gutural|Não: esse é o som do «g»."], "«jaar» ≈ «iár».", ["v-jaar"]),
    LI("zes", ["zes"], "seis", "O «z» é sonoro, como em «zebra».", ["v-zes"]),
    MA([("water","água"),("fiets","bicicleta"),("vis","peixe"),("zee","mar"),("school","escola")], "Palavras com w, f, v, z e sch.", ["v-water","v-fiets","v-vis","v-zee","v-school"]),
    AR("water","a água","het", "«Het water».", ["v-water"]),
    AR("fiets","a bicicleta","de", "«De fiets» — talvez a palavra mais neerlandesa de todas.", ["v-fiets"]),
    AR("jaar","o ano","het", "«Het jaar».", ["v-jaar"]),
    LI("de fiets", ["de fiets"], "a bicicleta", "«ie» = «i»; «ts» no fim.", ["v-fiets"]),
    FB("Ik ga naar ___.", ["school"], "«Naar school gaan» = ir para a escola (sem artigo).", ["v-school","v-gaan"], choices=["school","zes","vis"], tr="Vou para a escola."),
    TR("pt-nl","a bicicleta e o peixe", ["de fiets en de vis"], "Ambas usam «de».", ["v-fiets","v-vis","v-en"]),
    FE(["Ik","ga","naar","skool."], 3, "school", "Escola escreve-se com «sch»: school.", ["v-school"]),
  ], diff=2, mins=5)

L(6, "O «r», o «h» e o «-en» final", "Pormenores que fazem soar natural.",
  ["Pronunciar o «h» aspirado", "Saber que o «-n» final de «-en» é muitas vezes fraco"],
  vocab=[V("v-hond","hond","cão","noun","de","honden"), V("v-kat","kat","gato","noun","de","katten"),
         V("v-rood","rood","vermelho","adjective"), V("v-groot","groot","grande","adjective"),
         V("v-lopen","lopen","andar a pé|caminhar","verb",note="ik loop, jij loopt"),
         V("v-heel","heel","muito","adverb",note="heel groot = muito grande")],
  ex=[("De hond is groot.","O cão é grande."),("De kat is heel klein.","O gato é muito pequeno."),("Ik loop naar huis.","Vou a pé para casa.")],
  gram=[G("g-r-h-en","r, h e -en","O **h** ouve-se sempre, como no inglês *hello*: *hond*, *huis*. O **r** varia muito de região para região (vibrante ou gutural) e todos são aceites. No **-en** final dos verbos e plurais, muitos falantes quase não pronunciam o «n»: *lopen* ≈ «lope».",
    [("de hond","o cão"),("lopen","andar a pé")],
    "Em português o «h» é mudo; em neerlandês, omiti-lo pode mudar a palavra: «hand» (mão) vs «and» (não existe).")],
  review=["v-huis","v-klein","v-is"],
  exs=[
    LI("De hond is groot.", ["De hond is groot"], "O cão é grande.", "O «h» de «hond» é aspirado e «oo» é longo em «groot».", ["v-hond","v-groot"]),
    MA([("hond","cão"),("kat","gato"),("rood","vermelho"),("groot","grande")], "Vocabulário novo desta lição.", ["v-hond","v-kat","v-rood","v-groot"]),
    MC("Como se pronuncia o «h» de «huis»?", ["*Aspirado, como no inglês «hello»","Mudo, como em «hora»|Em neerlandês o «h» ouve-se sempre.","Como o «r» gutural|Não: esse é o som do «g»."], "O «h» neerlandês é sempre pronunciado.", ["v-huis"]),
    AR("hond","o cão","de", "«De hond».", ["v-hond"]),
    AR("kat","o gato","de", "«De kat» — plural «katten».", ["v-kat"]),
    CJ("lopen","ik","Ik ___ naar huis.", ["loop"], "lopen: ik loop, jij loopt. Na forma de «ik» o «oo» mantém-se longo: loop.", ["v-lopen"]),
    TR("nl-pt","De kat is heel klein.", ["O gato é muito pequeno"], "«Heel» antes de um adjetivo = muito.", ["v-kat","v-heel","v-klein"]),
    FB("De hond is ___ groot.", ["heel"], "«Heel groot» = muito grande.", ["v-heel","v-groot"], choices=["heel","rood","kat"], tr="O cão é muito grande."),
    WO("O gato é vermelho? Não, é castanho.", ["Is","de","kat","rood?","Nee,","bruin."], "Pergunta: o verbo vai para o início.", ["v-kat","v-rood","v-bruin"]),
    TR("pt-nl","O cão é grande.", ["De hond is groot"], "Adjetivo sem terminação depois de «is».", ["v-hond","v-groot"], bank=["De","hond","is","groot","kat","het"]),
  ], diff=2, mins=5)

L(7, "Ler em voz alta", "Revisão da unidade: todos os sons novos em frases curtas.",
  ["Ler frases com os sons típicos do neerlandês", "Distinguir grafias parecidas"],
  ex=[("Mijn zoon fietst naar school.","O meu filho vai de bicicleta para a escola."),("De maan is groot en geel.","A lua é grande e amarela.")],
  review=["v-zoon","v-zon","v-maan","v-man","v-huis","v-trein","v-boek","v-fiets","v-school","v-acht"],
  exs=[
    LI("Mijn zoon gaat naar school.", ["Mijn zoon gaat naar school"], "O meu filho vai para a escola.", "oo longo, g gutural, sch = s + ch.", ["v-zoon","v-gaan","v-school"]),
    MC("Qual é a palavra para «lua»?", ["*maan","man|«man» = homem.","mann|Esta grafia não existe."], "Vogal longa: aa.", ["v-maan"]),
    MC("Qual é a palavra para «comboio»?", ["*trein","tuin|«tuin» = jardim.","tijn|Esta palavra não existe."], "trein com «ei».", ["v-trein"]),
    MA([("zon","sol"),("zoon","filho"),("boek","livro"),("huis","casa"),("acht","oito")], "Revisão de pares e sons.", ["v-zon","v-zoon","v-boek","v-huis","v-acht"]),
    FE(["Het","boek","is","bluaw."], 3, "blauw", "Azul escreve-se «blauw».", ["v-blauw"]),
    TR("nl-pt","De fiets is oud.", ["A bicicleta é velha"], "oud ≈ «âut».", ["v-fiets","v-oud"]),
    LI("Het water is koud.", ["Het water is koud"], "A água está fria.", "w entre v e u; ou ≈ «âu».", ["v-water","v-koud"]),
    TR("pt-nl","A casa é pequena e velha.", ["Het huis is klein en oud"], "Dois adjetivos ligados por «en».", ["v-huis","v-klein","v-oud"], bank=["Het","huis","is","klein","en","oud","De"]),
    CO("text","Na rua", "Mijn huis is klein en oud. De deur is blauw. Mijn zoon gaat met de fiets naar school.",
       [("De que cor é a porta?", ["*Azul","Castanha","Vermelha"]),("Como vai o filho para a escola?", ["*De bicicleta","De comboio","A pé"])],
       "«met de fiets» = de bicicleta.", ["v-deur","v-blauw","v-fiets"]),
    SW("Escreva uma frase sobre a sua casa (pequena/grande, velha, de que cor é a porta…).", ["Mijn huis is [klein|groot]","Mijn huis is [klein|groot] en oud","De deur is [blauw|rood|bruin]"],
       ["Usa «mijn huis» ou «de deur»","Usa «is» + um adjetivo (klein, groot, oud, blauw…)"], 3, "Modelo: «Mijn huis is klein en oud.»", ["v-huis"]),
  ], diff=2, mins=6)

W()
